#!/usr/bin/env python3
"""Build local Korea-map introduction and beta guide from verified run assets."""
from __future__ import annotations

import hashlib
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
REPORTS = ROOT / 'reports'
RUNTIME = ROOT / '.runtime/korea-map-20261024'
INTRO = 'axiom-korea-map-introduction-20261024.html'
BETA = 'axiom-korea-map-beta-guide-20261024.html'

CSS = '''
:root{--bg:#10171b;--panel:#182328;--line:#34464b;--ink:#eef3ed;--muted:#b0c1c3;--mint:#b8f7cd;--orange:#ffc192;--blue:#b4d3ff;--font:"Pretendard","Apple SD Gothic Neo","Noto Sans KR",sans-serif}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:80px}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font);word-break:keep-all}a{color:inherit;text-underline-offset:4px}button,input{font:inherit}button,a,input{outline-offset:4px}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--blue)}button{cursor:pointer}header{display:flex;align-items:center;justify-content:space-between;padding:21px max(5vw,24px);border-bottom:1px solid var(--line);gap:20px}.brand{letter-spacing:.18em;font-weight:800;text-decoration:none;font-size:22px}nav{display:flex;gap:22px;align-items:center;font-size:12px;color:var(--muted)}main{max-width:1400px;margin:auto;padding:0 5vw}section{padding:64px 0;border-bottom:1px solid var(--line)}.eyebrow,.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.eyebrow{font-size:11px;letter-spacing:.14em;color:var(--mint);margin-bottom:22px}h1,h2,h3,p{margin:0}h1{font-size:clamp(40px,5.6vw,78px);line-height:1.08;letter-spacing:-.06em;font-weight:650}h2{font-size:clamp(30px,3.5vw,48px);line-height:1.16;letter-spacing:-.045em}h3{font-size:21px;letter-spacing:-.03em}p{line-height:1.65}.lede{font-size:18px;color:var(--muted);max-width:670px;margin-top:24px}.hero{display:grid;grid-template-columns:1.35fr 1fr;gap:52px;align-items:center;padding-top:72px}.mint{color:var(--mint)}.muted,.small{color:var(--muted)}.small{font-size:12px;line-height:1.6}.stats{display:grid;grid-template-columns:1fr 1fr;gap:28px}.stat{border-top:1px solid var(--line);padding-top:20px}.stat strong{font-size:44px;font-weight:550;letter-spacing:-.04em;display:block}.stat span{font-size:13px;color:var(--muted);display:block;margin-top:6px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:28px}.button,button{border:1px solid var(--line);padding:11px 15px;border-radius:5px;background:var(--panel);color:var(--ink);font-size:13px;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.button.accent,button[aria-pressed=true]{color:#14241b;background:var(--mint);border-color:var(--mint);font-weight:700}.section-head{display:flex;justify-content:space-between;align-items:end;gap:32px;margin-bottom:30px}.section-head p{max-width:480px}.run-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:15px}.player{background:#0a1114;border:1px solid var(--line);border-radius:9px;overflow:hidden}.player-grid{display:grid;grid-template-columns:1.65fr 1fr}.rgb-panel{position:relative;background:#182227;min-width:0}.rgb-panel img{display:block;width:100%;aspect-ratio:16/9;object-fit:contain}.label{position:absolute;top:14px;left:14px;background:#10171bdd;padding:7px 10px;border-radius:3px;font-size:10px;letter-spacing:.09em}.map-panel{padding:20px;border-left:1px solid var(--line);min-width:0;display:flex;flex-direction:column}.map-panel svg{width:100%;height:240px;flex:1;background:#121d22;margin:12px 0}.map-panel .legend{display:flex;flex-wrap:wrap;gap:15px;font-size:11px;color:var(--muted)}.controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap;padding:15px 20px;border-top:1px solid var(--line)}.controls input{flex:1;min-width:140px;accent-color:var(--mint)}.controls output{font-size:12px;min-width:150px}.player-bottom{padding:14px 20px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;align-items:center}.live-metrics{display:flex;gap:20px;flex-wrap:wrap;font-size:12px}.live-metrics b{font-size:17px;margin-left:7px;color:var(--mint)}.table-wrap{overflow-x:auto;margin-top:28px}table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}th,td{text-align:left;padding:15px 12px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:500}td:first-child,th:first-child{padding-left:0}.pass{color:var(--mint)}.fail{color:var(--orange)}.callout{border-left:3px solid var(--orange);background:#2a2521;padding:24px 28px;margin-top:30px;display:grid;grid-template-columns:1fr auto;gap:20px;align-items:center}.callout p{margin-top:9px;font-size:14px;color:#e3cec0}.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:30px}.card{border:1px solid var(--line);background:var(--panel);padding:26px;border-radius:6px}.card .num{font:12px ui-monospace,monospace;color:var(--mint);display:block;margin-bottom:19px}.card p{font-size:14px;color:var(--muted);margin-top:12px}.split{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-top:30px}.boundary{background:#e4eadf;color:#16251f;padding:30px;border-radius:6px}.boundary p{margin-top:15px;font-size:14px}.source-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:30px;margin-top:30px}.source-grid .card{padding:26px}details{margin-top:25px;border-top:1px solid var(--line);padding-top:18px}summary{cursor:pointer;font-size:13px}pre{font:11px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted)}footer{padding:35px 5vw 45px;color:var(--muted);max-width:1400px;margin:auto;font-size:12px}.checklist{display:grid;gap:13px;margin-top:20px}.checklist label{display:flex;align-items:flex-start;gap:12px;padding:15px;background:var(--panel);border:1px solid var(--line);border-radius:4px;font-size:14px;line-height:1.5}.checklist input{width:18px;height:18px;flex:none;accent-color:var(--mint)}.task{display:grid;grid-template-columns:80px 1fr;gap:20px;padding:30px 0;border-bottom:1px solid var(--line)}.task-number{font:32px ui-monospace,monospace;color:var(--mint)}.task p{margin-top:12px;color:var(--muted)}.task .done{margin-top:18px;font-size:13px;color:var(--ink)}.task:last-child{border-bottom:0}.evidence-img{width:100%;border:1px solid var(--line);border-radius:5px;margin-top:24px}code{overflow-wrap:anywhere}.notice{font-size:13px;color:var(--muted);margin-top:20px;max-width:950px}@media(max-width:900px){.hero,.source-grid{grid-template-columns:1fr}.hero{gap:35px}.stats{grid-template-columns:repeat(4,1fr)}.stat strong{font-size:32px}.player-grid{grid-template-columns:1fr}.map-panel{border-left:0;border-top:1px solid var(--line)}.map-panel svg{height:200px;flex:auto}.flow{grid-template-columns:1fr 1fr}.section-head{display:block}.section-head p{margin-top:18px}.split{grid-template-columns:1fr}}@media(max-width:550px){header{align-items:start}nav{gap:13px;flex-wrap:wrap;justify-content:end}main{padding:0 22px}section{padding:42px 0}.stats{grid-template-columns:1fr 1fr}.flow{grid-template-columns:1fr}.callout{grid-template-columns:1fr}.task{grid-template-columns:40px 1fr;gap:12px}.player-bottom{display:block}.player-bottom a{display:inline-block;margin-top:15px}.live-metrics{gap:12px}th,td{padding:12px 10px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;color:#15251c}header,nav,.controls,button,.actions{display:none}section{break-inside:avoid;padding:30px 0}.card,.player,.rgb-panel,.map-panel{background:white;color:#15251c}.muted,.small,.lede,th,.card p{color:#42534b}.mint,.pass{color:#17693a}.fail{color:#9b3b06}.callout{background:#fff1e8}.stats strong{font-size:32px}h1{font-size:46px}h2{font-size:30px}}
'''


def page(title, body, script=''):
    return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="실제 세종 OSM 도로의 원본 보존, CARLA 실행, RGB 재생과 Case 조사 · 확인한 범위를 담은 AXIOM 한국 지도 베타"><title>{html.escape(title)}</title><style>{CSS}</style></head><body><header><a class="brand" href="{INTRO}">AXIOM</a><nav><a href="{INTRO}">한국 지도 소개</a><a href="{BETA}">베타 과제</a><a href="axiom-platform-introduction-20261011.html">전체 플랫폼</a></nav></header><main>{body}</main><footer>AXIOM · KOREA ROAD PILOT · 2026.10.24<br>© OpenStreetMap contributors · <a href="https://www.openstreetmap.org/copyright">ODbL 이용조건</a> · CARLA renderer / simulator ground truth · 실차·물리 센서 검증 아님</footer>{script}</body></html>'''


def main():
    assets = json.loads((REPORTS / 'korea-map-assets-20261024/assets.json').read_text())
    accepted = json.loads((RUNTIME / 'case-acceptance.json').read_text())
    case = accepted['case']
    runs = assets['runs']
    if len(runs) != 4 or not accepted['ui_resume_verified'] or not accepted['export_verified']:
        raise ValueError('Four actual runs and completed Case acceptance are required')
    source = json.loads((RUNTIME / 'source-registration.json').read_text())['source']
    case_url = f"http://127.0.0.1:5360/#object-sim?project=default&execution={case['object_sim_evidence']['execution_id']}&scene_case={case['id']}&scene_case_revision={case['revision']}"
    library_url = f"http://127.0.0.1:5360/#object-sim?project=default&mode=map-sources&source={source['id']}&revision=1&source_hash={source['sha256']}"
    scenario_url = 'http://127.0.0.1:5360/#object-sim?project=default&mode=city&scenario=scenario2_0eace5f76b114ddf8864f33671f64631&revision=1'
    rows = ''
    for run in runs:
        m = run['metrics'][0] if isinstance(run['metrics'], list) else run['metrics']
        verdict = run['verdict']
        rows += f'''<tr><td>{html.escape(run['label'])}</td><td>실행 완료</td><td>{m['distance_travelled_m']:.3f} m</td><td>{m['lateral_error_p95_m']:.3f} m</td><td>{m['goal_error_m']:.3f} m</td><td>{len(run['frames'])}장</td><td class="{verdict}">{'통과' if verdict == 'pass' else '미통과'}</td></tr>'''
    body = f'''
<section class="hero"><div><div class="eyebrow">KOREA ROADS · ACTUAL NATIVE EXECUTION</div><h1>한국의 도로를,<br><span class="mint">반복 가능한<br>시험으로.</span></h1><p class="lede">세종의 공개 도로에서 출발해, 원본과 가정을 보존하고 CARLA 주행·RGB·조사 Case까지 연결했습니다.</p><div class="actions"><a class="button accent" href="#evidence">실제 주행 보기 ↓</a><a class="button" href="{BETA}">베타 과제 시작</a></div><p class="notice">도움4로 · 도움6로 · 다솜3로<br>OSM 기반 도로 형상입니다. 건물·도시 풍경이나 측량 정밀지도를 재현한 결과는 아닙니다.</p></div><div class="stats"><div class="stat"><strong>1.639<span style="display:inline"> km</span></strong><span>선택 OSM 중심선 합계</span></div><div class="stat"><strong>1,682</strong><span>엔진에서 읽은 차로 노드</span></div><div class="stat"><strong>4</strong><span>실제 주행 실행 · 고정 Seed 42</span></div><div class="stat"><strong>3 <span style="display:inline">/ 1</span></strong><span>고정 기준 통과 / 미통과</span></div></div></section>
<section id="evidence"><div class="section-head"><div><div class="eyebrow">01 · FROM MAP TO MOTION</div><h2>같은 지도에서,<br>실제 움직임을 확인합니다.</h2></div><p class="small">아래 영상은 봉인된 CARLA BGRA8 프레임을 PNG로 무손실 변환한 보존 재생입니다. 5 Hz 표본 사이에 새 영상을 생성하지 않습니다. 오른쪽은 저장된 좌표의 도식입니다.</p></div><div class="run-tabs" id="run-tabs" role="group" aria-label="주행 선택"></div><div class="player"><div class="player-grid"><div class="rgb-panel"><span class="label">CARLA RENDERER · 640 × 360 · RETAINED RGB</span><img id="rgb" alt="선택한 세종 도로 실행의 실제 CARLA RGB 프레임"></div><div class="map-panel"><div class="small" id="run-name"></div><svg id="route" role="img" aria-label="목표 경로와 실제 차량 궤적 도식"></svg><div class="legend"><span>┄ 목표 경로</span><span class="mint">━ 실제 궤적</span><span class="fail">● 현재 위치</span></div></div></div><div class="controls"><button id="play" type="button">재생</button><input id="timeline" type="range" min="0" value="0" step="1" aria-label="보존 RGB 프레임"><output id="time"></output></div><div class="player-bottom"><div class="live-metrics"><span>실제 속도<b id="speed"></b></span><span>순간 경로 오차<b id="error"></b></span></div><a id="open-run" class="small" href="#">정상 제품 Viewer에서 열기 ↗</a></div></div><div class="table-wrap"><table><thead><tr><th>저장 조건</th><th>실행</th><th>실제 이동</th><th>경로 오차 P95</th><th>종료 목표 거리</th><th>RGB</th><th>기준 평가</th></tr></thead><tbody>{rows}</tbody></table></div><p class="notice">고정 기준: 경로 오차 P95 ≤ 0.5 m · 목표 거리 ≤ 2 m · 마지막 속도 ≤ 0.2 m/s · native 접촉 없음. 네 실행 모두 RGB drop 0, 접촉 관측 0입니다. 반복 통계나 도로 전체의 주행 가능성을 입증한 시험은 아닙니다.</p><div class="callout"><div><h3>우회전의 미통과도, 다음 조사의 출발점으로.</h3><p>P95 0.715 m가 기준 0.5 m를 넘었습니다. 13.65 s의 순간 오차 0.809 m를 Case로 고정했습니다. 지도 형상과 제어 추종의 기여 원인은 아직 분리하지 않았습니다.</p></div><a class="button" href="{html.escape(case_url)}">원본 시점의 Case 열기 ↗</a></div></section>
<section><div class="eyebrow">02 · ONE CONNECTED WORKFLOW</div><h2>원본에서 조사까지,<br>한 흐름으로 이어집니다.</h2><div class="flow"><article class="card"><span class="num">01 / SOURCE</span><h3>원본을 보존</h3><p>XODR·SHP ZIP의 bytes, 출처, 권리와 개정을 고정합니다. 이번 지도는 상위 OSM 등 첨부 5개도 보존했습니다.</p></article><article class="card"><span class="num">02 / CONVERT</span><h3>변환과 가정을 구분</h3><p>좌표 변환·보완 폭·교차로 가정을 기록하고 지원하지 않는 입력은 진단과 함께 중단합니다.</p></article><article class="card"><span class="num">03 / QUALIFY</span><h3>실제 엔진에서 확인</h3><p>큐를 통해 지도 생성과 차로 읽기를 실행했습니다. 입력과 native OpenDRIVE 해시가 일치합니다.</p></article><article class="card"><span class="num">04 / PUBLISH</span><h3>확인한 개정만 사용</h3><p>원본·변환·실행 근거가 일치하는 지도만 프로젝트 안에 게시합니다. 공개 인터넷 배포와는 별개입니다.</p></article><article class="card"><span class="num">05 / EXECUTE</span><h3>편집하고 다시 실행</h3><p>실제 UI에서 좌회전 r1의 속도·시간을 변경하고 r2로 저장한 뒤 실행했습니다. 두 개정과 결과는 각각 남습니다.</p></article><article class="card"><span class="num">06 / INVESTIGATE</span><h3>문제 시점을 Case로</h3><p>프레임·실행·시나리오·지도 계보를 고정합니다. 새로고침 후 같은 시점으로 돌아가고 봉인 Case를 내보냅니다.</p></article></div><div class="actions"><a class="button accent" href="{html.escape(library_url)}">한국·외부 지도 라이브러리 ↗</a><a class="button" href="{BETA}">참가자 안내</a></div></section>
<section><div class="eyebrow">03 · SOURCE COVERAGE</div><h2>지금 제공되는 지도와,<br>다음 입력을 구분합니다.</h2><div class="source-grid"><div><div class="card"><h3>지금 사용 · 세종 OSM 도로</h3><p>8개 way를 선택해 16개 OpenDRIVE road와 3개 junction으로 사전 변환했습니다. 차로 폭 3.5 m 기본값, 누락 차로 수 추론과 생성 교차로가 포함됩니다. 고도 실측값과 신호 프로그램은 제공하지 않습니다.</p><p>OSM → XODR 사전 변환 도구를 사용한 뒤 일반 라이브러리에 등록했습니다. OSM 파일의 UI 직접 변환 기능으로 표시하지 않습니다.</p></div><div class="card" style="margin-top:16px"><h3>준비된 입력부 · NGII SHP ZIP</h3><p>A1/A2/B2 선택 변환과 좌표·연결·폭 진단을 구현했습니다. 합성 SHP 31개 검사는 통과했으나 실제 NGII 원본이 없어 실제 자료 인수와 주행 검증은 남아 있습니다.</p><p><a href="https://map.ngii.go.kr/ms/pblictn/preciseRoadMap.do">NGII 공식 정밀도로지도 안내 ↗</a></p></div></div><aside class="boundary"><h3>검증 범위</h3><p><strong>확인함</strong><br>원본 export 일치 · 실제 native 지도 로드 · 개정 저장·주행·RGB 재생 · Case 저장과 재개</p><p><strong>남아 있음</strong><br>실제 NGII 원본 · 신호·차로 규칙 인수 · 도시 asset · 도로 형상/제어 상관 검증 · 실차 및 물리 센서 검증</p><p>현재 결과는 CARLA GT 피드백 제어 범위입니다. 한국 도로 전체 지원, 정밀지도 정확도, 실제 차량 안전 판정으로 확대하지 않습니다.</p></aside></div><details><summary>원본 · 실행 · 보고서 근거</summary><p class="small" style="margin-top:16px">원본 취득 2026-10-24 · ODbL-1.0 · 각 입력 개정과 content hash 보존</p><pre>{html.escape(json.dumps({'source': {'id':source['id'],'revision':1,'manifest_sha256':source['sha256'],'xodr_sha256':source['source_sha256']},'runs':[{'execution_id':r['execution_id'],'manifest_hash':r['manifest_hash'],'verdict':r['verdict']} for r in runs],'case':{'id':case['id'],'revision':case['revision'],'manifest_hash':case['manifest_hash']}},ensure_ascii=False,indent=2))}</pre><div class="actions"><a href="korea-map-assets-20261024/provenance.json">미디어 변환 근거</a><a href="axiom-korea-map-20261024.sources.json">보고서 source manifest</a><a href="../docs/korea-map-pilot.md">구현·인수 상세</a></div></details></section>'''
    data = json.dumps(assets, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
    script = '''<script type="application/json" id="evidence-data">''' + data + '''</script><script>
const data=JSON.parse(document.getElementById('evidence-data').textContent),$=id=>document.getElementById(id);let run,index=0,timer=null;const ns='http://www.w3.org/2000/svg';
function stop(){if(timer)clearInterval(timer);timer=null;$('play').textContent='재생'}
function path(d,color,width,dash){const el=document.createElementNS(ns,'path');el.setAttribute('d',d);el.setAttribute('fill','none');el.setAttribute('stroke',color);el.setAttribute('stroke-width',width);el.setAttribute('vector-effect','non-scaling-stroke');if(dash)el.setAttribute('stroke-dasharray',dash);$('route').append(el);return el}
function draw(){const f=run.frames[index];$('rgb').src=f.src;$('timeline').value=index;$('time').textContent=f.time_s.toFixed(2)+' s · frame '+f.scene_index;$('speed').textContent=f.actual_speed_mps.toFixed(2)+' m/s';$('error').textContent=f.path_error_m.toFixed(3)+' m';const svg=$('route');svg.replaceChildren();const all=[...run.route,...run.frames.map(x=>x.pose)],xs=all.map(p=>p.x),ys=all.map(p=>p.y),xmin=Math.min(...xs)-8,ymin=Math.min(...ys)-8,w=Math.max(...xs)-xmin+8,h=Math.max(...ys)-ymin+8;svg.setAttribute('viewBox',[xmin,ymin,w,h].join(' '));const nearby=run.map.edges.filter(e=>e[0]>xmin-8&&e[0]<xmin+w+8&&e[1]>ymin-8&&e[1]<ymin+h+8);path(nearby.map(e=>'M'+e[0]+','+e[1]+'L'+e[2]+','+e[3]).join(' '),'#3e545b',1);path(run.route.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' '),'#c2d2d3',2,'5 4');path(run.frames.slice(0,index+1).map((v,i)=>(i?'L':'M')+v.pose.x+','+v.pose.y).join(' '),'#b8f7cd',3);const c=document.createElementNS(ns,'circle');c.setAttribute('cx',f.pose.x);c.setAttribute('cy',f.pose.y);c.setAttribute('r',Math.max(w,h)/45);c.setAttribute('fill','#ffc192');svg.append(c)}
function choose(i){stop();run=data.runs[i];index=Math.min(50,run.frames.length-1);$('timeline').max=run.frames.length-1;$('run-name').textContent=run.label+' · '+(run.verdict==='pass'?'저장 기준 통과':'저장 기준 미통과');$('open-run').href=run.ui_url;document.querySelectorAll('#run-tabs button').forEach((b,j)=>b.setAttribute('aria-pressed',j===i?'true':'false'));draw()}
data.runs.forEach((r,i)=>{const b=document.createElement('button');b.type='button';b.textContent=r.label;b.onclick=()=>choose(i);$('run-tabs').append(b)});$('timeline').oninput=e=>{stop();index=Number(e.target.value);draw()};$('play').onclick=()=>{if(timer){stop();return}if(index===run.frames.length-1)index=0;$('play').textContent='일시정지';timer=setInterval(()=>{if(index>=run.frames.length-1){stop();return}index++;draw()},200)};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});choose(Math.max(0,data.runs.findIndex(r=>r.key==='left_turn')));
</script>'''
